std::random_device rd;
std::mt19937 gen(rd());
// The Maxwell-Boltzmann distribution for each component of velocity is a Gaussian 
// with mean 0 and variance sigma^2 = k_B * T / m.
// In reduced units or specific MD contexts, k_B is often implicit or 1.0.
std::normal_distribution<double> dist(0.0, 1.0);

vec3 centerOfMassVelocity(0, 0, 0);
double totalMass = 0.0;

for (size_t i = 0; i < velocities.size(); ++i) {
    double mass = masses[i];
    double sigma = std::sqrt(temperature / mass);

    velocities[i].x = dist(gen) * sigma;
    velocities[i].y = dist(gen) * sigma;
    velocities[i].z = dist(gen) * sigma;

    centerOfMassVelocity += velocities[i] * mass;
    totalMass += mass;
}

if (totalMass > 0) {
    centerOfMassVelocity = centerOfMassVelocity / totalMass;
    for (size_t i = 0; i < velocities.size(); ++i) {
        velocities[i] -= centerOfMassVelocity;
    }
}

